pm.test("PayPal OAuth authentication succeeds", function () {
    pm.response.to.have.status(200);
});

const clientId = await pm.vault.get("paypal_client_id");
const clientSecret = await pm.vault.get("paypal_client_secret");

if (!clientId || !clientSecret) {
    throw new Error("PayPal Sandbox credentials are missing from Vault.");
}

const credentials = btoa(clientId + ":" + clientSecret);

const tokenResponse = await pm.sendRequest({
    url: "https://api-m.sandbox.paypal.com/v1/oauth2/token",
    method: "POST",
    header: {
        Authorization: "Basic " + credentials,
        "Content-Type": "application/x-www-form-urlencoded"
    },
    body: {
        mode: "urlencoded",
        urlencoded: [
            { key: "grant_type", value: "client_credentials" }
        ]
    }
});

if (tokenResponse.code !== 200) {
    throw new Error("PayPal OAuth authentication failed.");
}

const token = tokenResponse.json().access_token;

if (!token) {
    throw new Error("PayPal did not return an access token.");
}

pm.variables.set("paypal_access_token", token);

const order = pm.response.json();
const unit = order.purchase_units[0];
const capture = unit.payments.captures[0];

pm.test("Order retrieval succeeds", () => {
    pm.response.to.have.status(200);
});

pm.test("Order is completed", () => {
    pm.expect(order.status).to.eql("COMPLETED");
});

pm.test("Capture is completed", () => {
    pm.expect(capture.status).to.eql("COMPLETED");
});

pm.test("Payment is $1.00 USD", () => {
    pm.expect(unit.amount.currency_code).to.eql("USD");
    pm.expect(Number(unit.amount.value)).to.eql(1);
});

pm.test("Capture matches order amount", () => {
    pm.expect(capture.amount.currency_code)
      .to.eql(unit.amount.currency_code);
    pm.expect(Number(capture.amount.value))
      .to.eql(Number(unit.amount.value));
});

pm.test("Settlement breakdown reconciles", () => {
    const breakdown = capture.seller_receivable_breakdown;
    const gross = Number(breakdown.gross_amount.value);
    const fee = Number(breakdown.paypal_fee.value);
    const net = Number(breakdown.net_amount.value);

    pm.expect(Math.abs(gross - fee - net))
      .to.be.below(0.001);
});
